import{_ as a,o as r,c as i,ag as e}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"2026上半年AI产业全景","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/2026-h1-ai-landscape.md","filePath":"topics/ai-system-architecture/2026-h1-ai-landscape.md"}'),l={name:"topics/ai-system-architecture/2026-h1-ai-landscape.md"};function o(d,t,n,h,s,u){return r(),i("div",null,[...t[0]||(t[0]=[e('<h1 id="_2026上半年ai产业全景" tabindex="-1">2026上半年AI产业全景 <a class="header-anchor" href="#_2026上半年ai产业全景" aria-label="Permalink to &quot;2026上半年AI产业全景&quot;">​</a></h1><blockquote><p>来源：Gartner、QuestMobile、路透社、华泰证券、SNE Research、IDC、赛迪顾问 日期：2026-06-30</p></blockquote><hr><h2 id="一、大模型竞争-中国调用量连续9周全球第一" tabindex="-1">一、大模型竞争：中国调用量连续9周全球第一 <a class="header-anchor" href="#一、大模型竞争-中国调用量连续9周全球第一" aria-label="Permalink to &quot;一、大模型竞争：中国调用量连续9周全球第一&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>中国</th><th>美国</th></tr></thead><tbody><tr><td>上周Token调用量</td><td>20.39万亿（+8.4%）</td><td>4.25万亿（-26.22%）</td></tr><tr><td>全球占比变化</td><td>持续上升</td><td>从一年前72%降至33%</td></tr></tbody></table><h3 id="关键玩家" tabindex="-1">关键玩家 <a class="header-anchor" href="#关键玩家" aria-label="Permalink to &quot;关键玩家&quot;">​</a></h3><ul><li><strong>智谱GLM-5.2</strong>：周调用量2.11万亿Token（+66%），开源模型全球第一</li><li><strong>DeepSeek V4</strong>：正式版7月中旬上线，引入峰谷定价（高峰9-12点、14-18点价格翻倍）</li><li><strong>豆包</strong>：月活3.45亿，中国AI原生App第一</li><li><strong>千问</strong>：月活1.66亿</li><li><strong>DeepSeek</strong>：月活1.27亿</li></ul><h3 id="openai与anthropic" tabindex="-1">OpenAI与Anthropic <a class="header-anchor" href="#openai与anthropic" aria-label="Permalink to &quot;OpenAI与Anthropic&quot;">​</a></h3><ul><li>OpenAI发布GPT-5.6 Sol预览版，编码与安全能力大幅升级，配备最强安全栈</li><li>Anthropic秘密递交S-1，估值逼近万亿美元，最快秋季上市</li></ul><hr><h2 id="二、ai芯片-寒武纪首登gartner领导者象限" tabindex="-1">二、AI芯片：寒武纪首登Gartner领导者象限 <a class="header-anchor" href="#二、ai芯片-寒武纪首登gartner领导者象限" aria-label="Permalink to &quot;二、AI芯片：寒武纪首登Gartner领导者象限&quot;">​</a></h2><p>2026年5月，Gartner发布《AI基础设施魔力象限》，<strong>寒武纪首次进入领导者象限</strong>，成为该榜单创立以来首个来自中国大陆的芯片企业。</p><h3 id="寒武纪核心能力" tabindex="-1">寒武纪核心能力 <a class="header-anchor" href="#寒武纪核心能力" aria-label="Permalink to &quot;寒武纪核心能力&quot;">​</a></h3><ul><li>自研MLU系列AI加速卡，云边端一体化架构</li><li>MLU590基于7nm，INT8算力512 TOPS，能效比领先A100约30%</li><li>下半年推出MLU700，3nm制程，目标2000 TOPS，直接对标英伟达B200</li><li>Q1 2026中国AI芯片市场份额15.3%，同比增长47%</li><li>开发者生态15万+（vs 英伟达CUDA 400万），差距仍大但增速快</li><li>科创板市值突破1万亿（6月30日），首支万亿市值科创板个股</li></ul><h3 id="全球ai芯片格局" tabindex="-1">全球AI芯片格局 <a class="header-anchor" href="#全球ai芯片格局" aria-label="Permalink to &quot;全球AI芯片格局&quot;">​</a></h3><ul><li>英伟达仍以82%份额占据统治地位，H200受控条件下批准部分中国采购，但H20后门事件引发信任危机</li><li>Q1 2026全球AI芯片市场规模187亿美元，同比增长28%</li><li>Gartner预测到2028年中国AI芯片自给率从12%提升至30%+</li><li>全球20余家半导体厂商发布涨价函，台积电3nm下半年报价上调15%</li></ul><h3 id="国产芯片进入大厂验证期" tabindex="-1">国产芯片进入大厂验证期 <a class="header-anchor" href="#国产芯片进入大厂验证期" aria-label="Permalink to &quot;国产芯片进入大厂验证期&quot;">​</a></h3><p>6月15日，路透社报道<strong>字节跳动正洽谈采购天数智芯5万颗推理芯片</strong>，用于豆包等AI产品。若落地，天数智芯将成为继华为昇腾、寒武纪之后，字节第三家主要国产GPU供应商。</p><ul><li>天数智芯2025年收入10.34亿元（+91.6%），推理产品智铠系列收入3.39亿元（+238.2%）</li><li>智铠兼容CUDA生态，迁移时间降低50%以上</li><li>华泰预计2026年收入可达30.4亿元，出货量同比增长139%至超10万颗</li></ul><p><strong>关键转折</strong>：从&quot;被迫选择国产&quot;到&quot;主动配置国产&quot;——不把鸡蛋放在一个篮子里，已成国内大厂共识。</p><hr><h2 id="三、ai基建-中国10万亿-全球军备竞赛" tabindex="-1">三、AI基建：中国10万亿，全球军备竞赛 <a class="header-anchor" href="#三、ai基建-中国10万亿-全球军备竞赛" aria-label="Permalink to &quot;三、AI基建：中国10万亿，全球军备竞赛&quot;">​</a></h2><h3 id="各国投资规模" tabindex="-1">各国投资规模 <a class="header-anchor" href="#各国投资规模" aria-label="Permalink to &quot;各国投资规模&quot;">​</a></h3><table tabindex="0"><thead><tr><th>国家/地区</th><th>投资规模</th><th>时间跨度</th></tr></thead><tbody><tr><td>中国</td><td>10万亿人民币</td><td>至2030年</td></tr><tr><td>美国</td><td>四大科技巨头2026年约6500亿美元</td><td>年度</td></tr><tr><td>欧洲</td><td>2000亿欧元</td><td>—</td></tr><tr><td>日本</td><td>1万亿日元</td><td>—</td></tr><tr><td>韩国</td><td>2600万亿韩元（约14万亿人民币）</td><td>十年</td></tr></tbody></table><h3 id="黄仁勋-ai五层蛋糕" tabindex="-1">黄仁勋&quot;AI五层蛋糕&quot; <a class="header-anchor" href="#黄仁勋-ai五层蛋糕" aria-label="Permalink to &quot;黄仁勋&quot;AI五层蛋糕&quot;&quot;">​</a></h3><ol><li><strong>能源</strong> — 电力是AI的物理约束</li><li><strong>芯片</strong> — 算力的物质基础</li><li><strong>基础设施</strong> — 数据中心、网络、光模块</li><li><strong>模型</strong> — 算法与训练</li><li><strong>应用</strong> — 最终价值交付</li></ol><p>中国在每一层都在加速。达沃斯论坛调查：约70%参会者认为能源和电网容量将成为未来五年制约AI增长的主要瓶颈。</p><h3 id="边缘计算-下一个战场" tabindex="-1">边缘计算：下一个战场 <a class="header-anchor" href="#边缘计算-下一个战场" aria-label="Permalink to &quot;边缘计算：下一个战场&quot;">​</a></h3><ul><li>爱芯元智累计出货近2亿颗芯片，自研&quot;爱芯通元&quot;混合精度NPU</li><li>地平线征程系列累计出货突破500万片，辅助驾驶国产市占率第二</li><li>华为昇腾累计出货超千万片</li><li>瑞芯微边缘计算芯片2025年出货突破8000万颗</li></ul><p>关键指标不再是峰值算力，而是<strong>工具链成熟度、模型迁移便利性、长期供货稳定性</strong>。</p><hr><h2 id="四、ai应用-从实验室到生产环境" tabindex="-1">四、AI应用：从实验室到生产环境 <a class="header-anchor" href="#四、ai应用-从实验室到生产环境" aria-label="Permalink to &quot;四、AI应用：从实验室到生产环境&quot;">​</a></h2><h3 id="中国ai原生app格局-截至2026年3月" tabindex="-1">中国AI原生App格局（截至2026年3月） <a class="header-anchor" href="#中国ai原生app格局-截至2026年3月" aria-label="Permalink to &quot;中国AI原生App格局（截至2026年3月）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>排名</th><th>App</th><th>月活用户</th></tr></thead><tbody><tr><td>1</td><td>豆包</td><td>3.45亿</td></tr><tr><td>2</td><td>千问</td><td>1.66亿</td></tr><tr><td>3</td><td>DeepSeek</td><td>1.27亿</td></tr></tbody></table><p>中国AI原生App月活用户总规模达4.4亿。</p><h3 id="行业落地" tabindex="-1">行业落地 <a class="header-anchor" href="#行业落地" aria-label="Permalink to &quot;行业落地&quot;">​</a></h3><ul><li><strong>金融</strong>：寒武纪+工商银行智能风控，欺诈检测准确率92%→98.7%，延迟降至5ms</li><li><strong>医疗</strong>：寒武纪+华大基因，全基因组分析48小时→6小时</li><li><strong>自动驾驶</strong>：寒武纪+比亚迪&quot;玄武&quot;智驾芯片定点车型超10款</li><li><strong>体育</strong>：寒武纪MLU用于NBA中国实时数据分析，一秒处理2000帧比赛画面</li><li><strong>AI制药</strong>：FDA首次以&quot;AI&quot;名义开出药品违规警告信（Purolea案），&quot;人在回路&quot;原则确立</li></ul><hr><h2 id="五、ai监管-全球三线并行" tabindex="-1">五、AI监管：全球三线并行 <a class="header-anchor" href="#五、ai监管-全球三线并行" aria-label="Permalink to &quot;五、AI监管：全球三线并行&quot;">​</a></h2><h3 id="中国" tabindex="-1">中国 <a class="header-anchor" href="#中国" aria-label="Permalink to &quot;中国&quot;">​</a></h3><ul><li>6月29日国常会：加快超大规模智算集群建设，实施&quot;人工智能+&quot;全产业行动，完善AI分级安全监管体系</li></ul><h3 id="欧盟" tabindex="-1">欧盟 <a class="header-anchor" href="#欧盟" aria-label="Permalink to &quot;欧盟&quot;">​</a></h3><ul><li>AI法案延期：高风险AI合规推迟16个月至2027年12月</li></ul><h3 id="美国" tabindex="-1">美国 <a class="header-anchor" href="#美国" aria-label="Permalink to &quot;美国&quot;">​</a></h3><ul><li>FDA 2025财年发出303封药品警告信（+60%），AI相关内容首次被纳入违规审查</li><li>核心原则：<strong>人在回路</strong>（Human-in-the-loop）——AI可起草、识别、打分，但最终负责的必须是人</li></ul><hr><h2 id="六、科技巨头动向" tabindex="-1">六、科技巨头动向 <a class="header-anchor" href="#六、科技巨头动向" aria-label="Permalink to &quot;六、科技巨头动向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>公司</th><th>动作</th></tr></thead><tbody><tr><td>微软</td><td>6月30日起取消内部Claude Code许可，数千工程师迁移至GitHub Copilot CLI</td></tr><tr><td>马斯克/xAI</td><td>Grok 4.5在特斯拉/SpaceX内部测试，今年每月发布一个全新从零训练的大模型</td></tr><tr><td>SpaceX</td><td>正式定名&quot;Starmind&quot;太空AI星座，规划百万颗在轨计算卫星</td></tr><tr><td>三星</td><td>十年1000万亿韩元投资，覆盖芯片/AI/储能</td></tr><tr><td>马斯克</td><td>新专机（卡塔尔赠予波音747-8）正式列装，24K金箔涂装</td></tr></tbody></table><hr><h2 id="七、关键趋势总结" tabindex="-1">七、关键趋势总结 <a class="header-anchor" href="#七、关键趋势总结" aria-label="Permalink to &quot;七、关键趋势总结&quot;">​</a></h2><ol><li><strong>中国AI从&quot;跟跑&quot;到&quot;并跑&quot;</strong>：大模型调用量全球第一，芯片进入Gartner领导者象限，应用月活4.4亿</li><li><strong>国产芯片从替代到主力</strong>：字节等大厂主动配置国产推理芯片，不再仅是被迫选择</li><li><strong>AI基建是下一个十年的确定性赛道</strong>：中国10万亿、全球数十万亿级投入</li><li><strong>边缘计算从云端下沉</strong>：出货量亿级，竞争焦点从算力转向生态</li><li><strong>监管框架成型</strong>：中美欧三线并行，&quot;人在回路&quot;成为共识</li><li><strong>能源是AI的阿喀琉斯之踵</strong>：70%达沃斯参会者认为电力将制约AI增长</li></ol>',51)])])}const b=a(l,[["render",o]]);export{q as __pageData,b as default};
